/* submul_1: rp[0..n) -= up[0..n)·v; returns the borrow word (∈ [0, v]) to
 * subtract from rp[n]. Knuth's multiply-subtract inner loop (and therefore
 * every Burnikel–Ziegler base case). Same two-chain structure as addmul_1:
 * an adds chain forms s_i = lo_i + hi_{i-1}, an sbcs chain subtracts s from
 * rp; the final sbcs borrow folds into the borrow word (the fold cannot
 * overflow — the true borrow word is ≤ v ≤ 2^64−1). */
static uint64_t bn_submul_1_ref(uint64_t *rp, const uint64_t *up, int32_t n, uint64_t v) {
    uint64_t borrow = 0;                    /* borrow word */
    for (int32_t i = 0; i < n; i++) {
        __uint128_t prod = (__uint128_t)up[i] * v;
        uint64_t lo = (uint64_t)prod, hi = (uint64_t)(prod >> 64);
        uint64_t s = lo + borrow;
        uint64_t c = s < lo;
        uint64_t r = rp[i];
        rp[i] = r - s;
        borrow = hi + c + (r < s);
    }
    return borrow;
}
#if defined(__aarch64__)
/*
 * As with addmul_1, keep the whole hot leaf in caller-saved registers.  The
 * previous inline-asm form made Clang spill six callee-saved registers around
 * every quotient digit.  This version pipelines four MUL/UMULH pairs, forms
 * the shifted product with one ADCS chain, then subtracts it with one SBCS
 * chain.  Prefixes of one and two limbs leave the main loop a multiple of four.
 */
__attribute__((naked, noinline, aligned(64)))
__attribute__((visibility("hidden")))
uint64_t bn_submul_1(uint64_t *rp, const uint64_t *up, int32_t n, uint64_t v) {
    __asm__(
        "adds x15, xzr, xzr\n"
        "tbz w2, #0, 1f\n"
        "ldr x4, [x1], #8\n"
        "mul x8, x4, x3\n"
        "umulh x12, x4, x3\n"
        "ldr x4, [x0]\n"
        "subs x8, x4, x8\n"
        "cinc x15, x12, lo\n"
        "str x8, [x0], #8\n"
        "1:\n"
        "tbz w2, #1, 2f\n"
        "ldp x4, x5, [x1], #16\n"
        "mul x8, x4, x3\n"
        "umulh x12, x4, x3\n"
        "mul x9, x5, x3\n"
        "umulh x13, x5, x3\n"
        "adds x8, x8, x15\n"
        "adcs x9, x9, x12\n"
        "ldp x4, x5, [x0]\n"
        "adc x15, x13, xzr\n"
        "subs x8, x4, x8\n"
        "sbcs x9, x5, x9\n"
        "cinc x15, x15, lo\n"
        "stp x8, x9, [x0], #16\n"
        "2:\n"
        "lsr x2, x2, #2\n"
        "cbz x2, 5f\n"
        "ldp x4, x5, [x1], #32\n"
        "ldp x6, x7, [x1, #-16]\n"
        "b 4f\n"
        "5:\n"
        "mov x0, x15\n"
        "ret\n"
        "nop\n"
        "nop\n"
        "3:\n"
        "ldp x4, x5, [x1], #32\n"
        "ldp x6, x7, [x1, #-16]\n"
        "subs x8, x16, x8\n"
        "sbcs x9, x17, x9\n"
        "stp x8, x9, [x0], #32\n"
        "sbcs x10, x12, x10\n"
        "sbcs x11, x13, x11\n"
        "stp x10, x11, [x0, #-16]\n"
        "cinc x15, x15, lo\n"
        "4:\n"
        "sub x2, x2, #1\n"
        "mul x8, x4, x3\n"
        "umulh x12, x4, x3\n"
        "mul x9, x5, x3\n"
        "umulh x13, x5, x3\n"
        "adds x8, x8, x15\n"
        "mul x10, x6, x3\n"
        "umulh x14, x6, x3\n"
        "adcs x9, x9, x12\n"
        "mul x11, x7, x3\n"
        "umulh x15, x7, x3\n"
        "adcs x10, x10, x13\n"
        "ldp x16, x17, [x0]\n"
        "adcs x11, x11, x14\n"
        "ldp x12, x13, [x0, #16]\n"
        "adc x15, x15, xzr\n"
        "cbnz x2, 3b\n"
        "subs x8, x16, x8\n"
        "sbcs x9, x17, x9\n"
        "sbcs x10, x12, x10\n"
        "sbcs x11, x13, x11\n"
        "stp x8, x9, [x0]\n"
        "stp x10, x11, [x0, #16]\n"
        "cinc x0, x15, lo\n"
        "ret\n"
    );
}
#else
#define bn_submul_1 bn_submul_1_ref
#endif

/* rp = mp - up*v, returning the borrow word.  Unlike bn_submul_1 this writes
 * from a distinct minuend, which lets GCD replay a Euclid row without first
 * copying mp into rp. */
static uint64_t bn_submul_from_1_ref(uint64_t *rp, const uint64_t *mp,
                                    const uint64_t *up, int32_t n,
                                    uint64_t v) {
    uint64_t borrow = 0;
    for (int32_t i = 0; i < n; i++) {
        __uint128_t prod = (__uint128_t)up[i] * v;
        uint64_t lo = (uint64_t)prod, hi = (uint64_t)(prod >> 64);
        uint64_t s = lo + borrow;
        uint64_t c = s < lo;
        uint64_t m = mp[i];
        rp[i] = m - s;
        borrow = hi + c + (m < s);
    }
    return borrow;
}
