    bn_dbl(tf,cc2,w); bn_dbl(tf,tf,w); bn_sub_n(te,te,tf,w);
    bn_dbl(tf,vinf,w);bn_dbl(tf,tf,w);bn_dbl(tf,tf,w);bn_dbl(tf,tf,w); bn_sub_n(te,te,tf,w);
    bn_shr1(te,w);
