WValue w_crypto_md5_bytes(WValue data) {
    const uint8_t *input;
    size_t len;
    char inline_buf[6];
    uint8_t digest[16];
    w_crypto_input_data(data, &input, &len, inline_buf);
    w_md5_digest(input, len, digest);
    return w_bytes_from_data(digest, 16);
}

